#!/usr/bin/env bash
# harness-managed: regenerated by 'harness init --install', do not edit
# Install the pinned harness dist into .harness/bin.
# Windows sibling: bootstrap.bat, same behaviour, same messages, same exit codes.
#
# Binaries are never committed to a product repository (spec section 4a item 1).
# This fetches the pinned dist from the internal Azure DevOps artifact feed,
# verifies every file in it against MANIFEST.toml, and only then moves
# anything into .harness/bin. Nothing unverified is ever put in place.
#
# The operator supplies the feed. There is no default and no public fallback:
#
#   HARNESS_DIST_FEED    base url or directory holding the dist archives. An
#                        https url on the internal feed, a file:// url, or a
#                        plain directory path for a mirror on disk.
#   HARNESS_DIST_TOKEN   optional bearer token for that feed. Read from the
#                        environment only, never from an argument.
#
# Exit codes: 0 ok, 1 failure, 4 missing prerequisite.
set -euo pipefail

readonly EXIT_FAILURE=1
readonly EXIT_MISSING_PREREQ=4
readonly PINNED_VERSION="0.1.14"
readonly MANIFEST_FILE="MANIFEST.toml"
readonly MANIFEST_VERSION="1"
readonly MAX_ENTRIES=4096

harness_dir="$(cd "$(dirname "$0")" && pwd)"
work_dir="$harness_dir/.bootstrap-tmp"

usage() {
  echo "Usage:"
  echo "  bootstrap.sh [--feed <url or dir>] [--version <v>] [--target <triple>]"
  echo "  bootstrap.sh --help"
  echo
  echo "Options:"
  echo "  --feed <url or dir>  internal artifact feed holding the dist archives."
  echo "                       Defaults to \$HARNESS_DIST_FEED."
  echo "  --version <v>        dist version to install. Defaults to $PINNED_VERSION."
  echo "  --target <triple>    dist target. Defaults to this platform."
  echo
  echo "\$HARNESS_DIST_TOKEN is sent as a bearer token when the feed is remote."
}

cleanup() {
  rm -rf "$work_dir"
}

fail() {
  echo "error: $1" >&2
  exit "$EXIT_FAILURE"
}

missing_prereq() {
  echo "error: $1" >&2
  exit "$EXIT_MISSING_PREREQ"
}

# Refuse an unsafe path outright rather than sanitising it. An entry that is
# absolute or holds '..' escapes the unpack directory, which is the classic zip
# slip, and a name holding anything else is a name the release pipeline never
# produced.
refuse_unsafe() {
  case "$1" in
    ""|/*|*/|*..*|*[!0-9A-Za-z._/-]*)
      fail "$archive_name refused: '$1' is not a plain relative path" ;;
  esac
}

feed="${HARNESS_DIST_FEED:-}"
version="$PINNED_VERSION"
target=""
archive_name=""

while [ "$#" -gt 0 ]; do
  case "$1" in
    -h|--help)
      usage
      exit 0 ;;
    --feed)
      [ "$#" -ge 2 ] || fail "--feed needs a value"
      feed="$2"
      shift 2 ;;
    --version)
      [ "$#" -ge 2 ] || fail "--version needs a value"
      version="$2"
      shift 2 ;;
    --target)
      [ "$#" -ge 2 ] || fail "--target needs a value"
      target="$2"
      shift 2 ;;
    *)
      echo "error: unknown argument '$1'" >&2
      echo "run 'bootstrap.sh --help' for usage" >&2
      exit "$EXIT_FAILURE" ;;
  esac
done

if [ -z "$target" ]; then
  case "$(uname -s 2>/dev/null || echo unknown)" in
    Linux) target="x86_64-unknown-linux-gnu" ;;
    MINGW*|MSYS*|CYGWIN*) target="x86_64-pc-windows-msvc" ;;
    *) missing_prereq "cannot tell which dist this platform needs, pass --target" ;;
  esac
fi

# The version and the target end up in a file name and in a url, so they are
# checked before either is built.
case "$version" in
  ""|*[!0-9A-Za-z.-]*) fail "'$version' is not a version this script will fetch" ;;
esac
case "$target" in
  ""|*[!0-9A-Za-z._-]*) fail "'$target' is not a target this script will fetch" ;;
esac

if [ -z "$feed" ]; then
  missing_prereq "no artifact feed configured, set HARNESS_DIST_FEED to the internal feed or pass --feed"
fi

for tool in unzip sha256sum; do
  command -v "$tool" >/dev/null 2>&1 || missing_prereq "$tool not found on PATH"
done

archive_name="harness-dist-$version-$target.zip"

remote=0
source_dir=""
case "$feed" in
  https://*) remote=1 ;;
  http://*) fail "the feed must be https or a local mirror, '$feed' is plain http" ;;
  file://*) source_dir="${feed#file://}" ;;
  *://*) fail "the feed '$feed' uses a scheme this script does not fetch from" ;;
  *) source_dir="$feed" ;;
esac

rm -rf "$work_dir"
mkdir -p "$work_dir" || fail "cannot create the work directory $work_dir"
trap cleanup EXIT
archive="$work_dir/dist.zip"

if [ "$remote" -eq 1 ]; then
  command -v curl >/dev/null 2>&1 || missing_prereq "curl not found on PATH"
  url="${feed%/}/$archive_name"
  # https only, and a redirect is followed only to https and only three deep.
  #
  # Redirects were refused outright until a release store made that impossible:
  # the archive is one hop from the url that names it. What made refusing them
  # safe to relax is that it was never the only defence. Every file in the zip
  # is hashed against MANIFEST.toml before anything is moved into place, so a
  # redirect to a host nobody intended still has to produce the exact bytes the
  # pinned manifest names.
  #
  # --location-trusted is deliberately not used, so the bearer token is sent to
  # the feed and never forwarded to whatever it redirects to.
  set -- --fail --silent --show-error --proto "=https" \
    --location --proto-redir "=https" --max-redirs 3 \
    --output "$archive" "$url"
  if [ -n "${HARNESS_DIST_TOKEN:-}" ]; then
    # The token goes in on stdin, so it stays out of the process list.
    printf 'header = "Authorization: Bearer %s"\n' "${HARNESS_DIST_TOKEN}" |
      curl --config - "$@" || fail "cannot fetch $archive_name from the feed"
  else
    curl "$@" || fail "cannot fetch $archive_name from the feed"
  fi
else
  source_dir="${source_dir%/}"
  [ -f "$source_dir/$archive_name" ] || fail "no $archive_name in the feed at $source_dir"
  cp "$source_dir/$archive_name" "$archive" || fail "cannot copy $archive_name out of the feed"
fi

# Every entry is judged before anything is written to disk. Refusing here, and
# not after unpacking, is the whole point: an entry that escapes the unpack
# directory must never be created in the first place.
entry_list="$work_dir/entries.txt"
unzip -Z1 "$archive" >"$entry_list" || fail "$archive_name does not open as a zip"

entries=0
while IFS= read -r entry; do
  entries=$((entries + 1))
  [ "$entries" -le "$MAX_ENTRIES" ] || fail "$archive_name holds more than $MAX_ENTRIES entries"
  refuse_unsafe "$entry"
done <"$entry_list"
[ "$entries" -gt 0 ] || fail "$archive_name holds no files"

tree_dir="$work_dir/tree"
mkdir -p "$tree_dir"
unzip -qq "$archive" -d "$tree_dir" || fail "$archive_name does not unpack"

manifest="$tree_dir/$MANIFEST_FILE"
[ -f "$manifest" ] || fail "$archive_name carries no $MANIFEST_FILE"

declared="$(awk -F' = ' '{ sub(/\r$/, "") } /^manifest_version = /{print $2; exit}' "$manifest")"
[ "$declared" = "$MANIFEST_VERSION" ] ||
  fail "$MANIFEST_FILE declares format version '$declared', this script reads version $MANIFEST_VERSION"

declared="$(awk -F' = ' '{ sub(/\r$/, "") } /^version = /{print $2; exit}' "$manifest" | tr -d '"')"
[ "$declared" = "$version" ] ||
  fail "$MANIFEST_FILE names version '$declared', this install pinned '$version'"

declared="$(awk -F' = ' '{ sub(/\r$/, "") } /^target = /{print $2; exit}' "$manifest" | tr -d '"')"
[ "$declared" = "$target" ] ||
  fail "$MANIFEST_FILE names target '$declared', this install needs '$target'"

# One line per entry, tab separated. The field order is fixed by the generator,
# so an entry missing a path or a sha256 is a manifest this script must not
# pretend to understand.
records="$(awk '
  { sub(/\r$/, "") }
  /^path = / { p = $0; sub(/^path = "/, "", p); sub(/"$/, "", p); next }
  /^sha256 = / { s = $0; sub(/^sha256 = "/, "", s); sub(/"$/, "", s); next }
  /^bytes = / {
    if (p == "" || s == "") { print "BADENTRY"; exit }
    print p "\t" s "\t" $3
    p = ""; s = ""
  }
' "$manifest")"
case "$records" in
  *BADENTRY*) fail "$MANIFEST_FILE has an entry without a path or a sha256" ;;
esac

checked=0
installable=0
while IFS="$(printf '\t')" read -r entry_path entry_sha entry_bytes; do
  [ -n "$entry_path" ] || continue
  refuse_unsafe "$entry_path"
  file="$tree_dir/$entry_path"
  [ -f "$file" ] || fail "$MANIFEST_FILE lists $entry_path, $archive_name does not carry it"

  actual_sha="$(sha256sum "$file" | cut -d' ' -f1)"
  [ "$actual_sha" = "$entry_sha" ] ||
    fail "$entry_path does not match $MANIFEST_FILE: recorded $entry_sha, recomputed $actual_sha"

  actual_bytes="$(wc -c <"$file" | tr -d ' ')"
  [ "$actual_bytes" = "$entry_bytes" ] ||
    fail "$entry_path is $actual_bytes bytes, $MANIFEST_FILE records $entry_bytes"

  checked=$((checked + 1))
  case "$entry_path" in
    bin/*) installable=$((installable + 1)) ;;
  esac
done <<EOF
$records
EOF

[ "$checked" -gt 0 ] || fail "$MANIFEST_FILE lists no files"
[ "$installable" -gt 0 ] || fail "$MANIFEST_FILE pins nothing under bin/"

# Anything unpacked that the manifest does not cover is unverified content
# riding along with verified content. Every listed entry was just found, so
# equal counts mean the sets are equal.
irregular="$(find "$tree_dir" ! -type f ! -type d | wc -l | tr -d ' ')"
[ "$irregular" = "0" ] || fail "$archive_name unpacked something that is not a regular file"
present="$(find "$tree_dir" -type f | wc -l | tr -d ' ')"
covered=$((present - 1))
[ "$covered" -eq "$checked" ] ||
  fail "$archive_name holds $covered files beside $MANIFEST_FILE, the manifest covers $checked"

echo "ok: $checked files verified against $MANIFEST_FILE, hashes recomputed"

# Verified, so now it can move. The work directory is inside .harness, so this
# is a rename on one filesystem rather than a copy that can stop half way.
dest="$harness_dir/bin"
staged="$work_dir/staged-bin"
previous="$work_dir/previous-bin"
mv "$tree_dir/bin" "$staged" || fail "cannot stage the verified binaries"
if [ -d "$dest" ]; then
  mv "$dest" "$previous" || fail "cannot replace $dest, close anything still running from it"
fi
if ! mv "$staged" "$dest"; then
  if [ -d "$previous" ]; then
    mv "$previous" "$dest" || true
  fi
  fail "cannot move the verified binaries into $dest"
fi
chmod 0755 "$dest"/* 2>/dev/null || true

echo "ok: installed $installable files into $dest from $archive_name"
exit 0
